-- Agent phone lines (docs/plan.md §1.160, owner 2026-11-20): a number in the client's Twilio
-- subaccount can be one agent's own, at a monthly price per line (default $10). The days each line
-- was an active agent's, with the price that day, and the statement line kind that bills them.
-- A new table, a new column with a default and two loosened checks, so the previous Worker keeps
-- working (it inserts no `phone_line` lines). Generated by drizzle-kit; the grants, row-level
-- security and guard at the end are hand-written.
CREATE TABLE "billing_phone_line_day" (
	"tenant_id" uuid NOT NULL,
	"day" date NOT NULL,
	"phone_number" text NOT NULL,
	"agent_id" uuid NOT NULL,
	"agent_name" text NOT NULL,
	"monthly_price" numeric(14, 4) NOT NULL,
	"currency" text DEFAULT 'USD' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "billing_phone_line_day_tenant_id_day_phone_number_pk" PRIMARY KEY("tenant_id","day","phone_number"),
	CONSTRAINT "billing_phone_line_day_price_check" CHECK ("billing_phone_line_day"."monthly_price" >= 0),
	CONSTRAINT "billing_phone_line_day_number_check" CHECK ("billing_phone_line_day"."phone_number" ~ '^\+[1-9][0-9]{6,14}$')
);
